export const makeId=()=>crypto.randomUUID();
let connection,scope='guest';
export const storageName=()=>scope==='guest'?'vmet-studio-guest-v2':'vmet-studio-account-'+scope;
export function setStorageScope(id){const next=typeof id==='string'&&/^[a-zA-Z0-9_-]{1,100}$/.test(id)?id:'guest';if(next!==scope){connection?.close();connection=undefined;scope=next}}

export async function store(){if(connection)return connection;connection=await new Promise((resolve,reject)=>{const r=indexedDB.open(storageName(),1);r.onupgradeneeded=()=>{r.result.createObjectStore('assets',{keyPath:'id'});r.result.createObjectStore('projects')};r.onsuccess=()=>resolve(r.result);r.onerror=()=>reject(r.error)});return connection}
export async function read(key,table='projects'){const db=await store();return new Promise((resolve,reject)=>{const r=db.transaction(table).objectStore(table).get(key);r.onsuccess=()=>resolve(r.result);r.onerror=()=>reject(r.error)})}
export async function list(table='projects'){const db=await store();return new Promise((resolve,reject)=>{const r=db.transaction(table).objectStore(table).getAll();r.onsuccess=()=>resolve(r.result);r.onerror=()=>reject(r.error)})}
export async function put(key,value,table='projects'){const db=await store();return new Promise((resolve,reject)=>{const tx=db.transaction(table,'readwrite');tx.objectStore(table).put(value,key);tx.oncomplete=resolve;tx.onerror=()=>reject(tx.error)})}
export async function migrate(){const old=await read('current');if(old?.version===1){const id=old.projectId||'legacy-first';if(!await read('project:'+id))await put('project:'+id,{...old,projectId:id,updatedAt:old.updatedAt||new Date().toISOString(),revision:0});return id}}
export async function projects(){await migrate();return (await list()).filter(p=>p&&typeof p==='object'&&p.version===1&&p.projectId).filter((p,i,a)=>a.findIndex(x=>x.projectId===p.projectId)===i).sort((a,b)=>(b.updatedAt||'').localeCompare(a.updatedAt||''))}
export async function saveProject(snapshot){const db=await store();return new Promise((resolve,reject)=>{const tx=db.transaction('projects','readwrite'),s=tx.objectStore('projects'),key='project:'+snapshot.projectId,r=s.get(key);let next;r.onsuccess=()=>{if(r.result&&(r.result.revision||0)!==(snapshot.revision||0)){tx.abort();return}next={...snapshot,revision:(snapshot.revision||0)+1,updatedAt:new Date().toISOString()};s.put(next,key);s.put(next.projectId,'lastProjectId')};tx.oncomplete=()=>resolve(next);tx.onabort=()=>reject(new Error('Проект изменён в другой вкладке. Обновите страницу, чтобы не затереть изменения.'));tx.onerror=()=>reject(tx.error)})}
export function blankProject({name='Новый проект',aspect='9:16',preset='dynamic',brief='',targetDuration=30}={}){return {version:1,projectId:makeId(),revision:0,updatedAt:new Date().toISOString(),name,aspect,preset,brief,targetDuration,clips:[],selected:null,music:null,musicVolume:.25,originalAudio:true,captionsEnabled:false,cues:[],voiceNotes:'',messages:[],provider:'local',model:'',markers:[]}}
