export async function clearLocalData(){if(connection){connection.close();connection=undefined}return new Promise((resolve,reject)=>{const r=indexedDB.deleteDatabase(storageName());r.onsuccess=()=>{localStorage.removeItem('vmet-ai-endpoint');sessionStorage.removeItem('vmet-selected-model');resolve()};r.onerror=()=>reject(r.error);r.onblocked=()=>reject(new Error('Закройте другие вкладки студии. Удаление ожидает освобождения хранилища.'))})}

export async function legacyLibrary(){if(!indexedDB.databases)return null;const names=await indexedDB.databases();if(!names.some(d=>d.name==='vmet-studio-v1'))return null;const db=await new Promise((resolve,reject)=>{const r=indexedDB.open('vmet-studio-v1',1);r.onsuccess=()=>resolve(r.result);r.onerror=()=>reject(r.error)});try{const scan=table=>new Promise((resolve,reject)=>{const r=db.transaction(table).objectStore(table).getAll();r.onsuccess=()=>resolve(r.result);r.onerror=()=>reject(r.error)});return{projects:await scan('projects'),assets:await scan('assets')}}finally{db.close()}}
export async function importLegacyLibrary(){const legacy=await legacyLibrary();if(!legacy)throw new Error('Старая библиотека не найдена на этом домене');const db=await store();return new Promise((resolve,reject)=>{const tx=db.transaction(['assets','projects'],'readwrite');for(const a of legacy.assets)tx.objectStore('assets').put(a);const seen=new Set();for(const p of legacy.projects){if(!p||p.version!==1)continue;const old=p.projectId||'legacy-first';if(seen.has(old))continue;seen.add(old);const projectId='recovered-'+old;tx.objectStore('projects').put({...p,projectId,revision:0,updatedAt:new Date().toISOString()},'project:'+projectId)}tx.oncomplete=()=>resolve(seen.size);tx.onerror=()=>reject(tx.error)})}

export async function putAsset(value){const db=await store();return new Promise((resolve,reject)=>{const tx=db.transaction('assets','readwrite');tx.objectStore('assets').put(value);tx.oncomplete=resolve;tx.onerror=()=>reject(tx.error)})}

export async function deleteMediaAsset(id){const db=await store();return new Promise((resolve,reject)=>{const tx=db.transaction(['assets','projects'],'readwrite'),ps=tx.objectStore('projects');tx.objectStore('assets').delete(id);let affected=0;const cursor=ps.openCursor();cursor.onsuccess=()=>{const c=cursor.result;if(!c)return;const p=c.value;if(p?.version===1&&p.projectId&&String(c.key).startsWith('project:')&&(p.music===id||p.clips?.some(x=>x.assetId===id))){const clips=(p.clips||[]).filter(x=>x.assetId!==id);c.update({...p,clips,music:p.music===id?null:p.music,selected:clips.some(x=>x.id===p.selected)?p.selected:clips[0]?.id||null,messages:(p.messages||[]).map(m=>({...m,plan:undefined})),revision:(p.revision||0)+1,updatedAt:new Date().toISOString()});affected++}c.continue()};tx.oncomplete=()=>resolve({affected});tx.onerror=()=>reject(tx.error);tx.onabort=()=>reject(tx.error)})}
